META = dict(nama="Fishery", jp="漁業", emoji="🐟", co="漁業会社")
SPEC = dict(kerja="魚の扱いや船の安全にしっかり気をつけて仕事をしている", kerja_id="bekerja dengan memperhatikan penanganan ikan dan keselamatan kapal", soal={
 "shibou-01": ("なぜ漁業の仕事を選びましたか。", "Mengapa Anda memilih pekerjaan perikanan?", "私の町は海の近くで、小さいころから漁師さんを見ていました。魚を取る仕事にあこがれていました。", "Kota saya dekat laut dan sejak kecil saya melihat nelayan. Saya mengagumi pekerjaan menangkap ikan.", [("漁業", "perikanan"), ("漁師", "nelayan"), ("海", "laut"), ("あこがれる", "mengagumi")]),
 "shibou-02": ("なぜ日本で漁業を学びたいですか。", "Mengapa Anda ingin belajar perikanan di Jepang?", "日本の漁業は、魚の品質を守る技術が高いと聞きました。その技術を学んで、将来に生かしたいです。", "Saya dengar perikanan Jepang punya teknik tinggi untuk menjaga kualitas ikan. Saya ingin mempelajarinya dan memanfaatkannya di masa depan.", [("技術", "teknik"), ("品質", "kualitas"), ("学ぶ", "belajar"), ("生かす", "memanfaatkan")]),
 "shibou-04": ("この仕事に興味を持った理由は何ですか。", "Apa alasan Anda tertarik pada pekerjaan ini?", "自然の中で働くのが好きです。取った魚を、みんなに食べてもらえるのがうれしいです。", "Saya suka bekerja di alam. Saya senang ikan yang saya tangkap bisa dimakan banyak orang.", [("興味", "minat"), ("自然", "alam"), ("やりがい", "rasa bermakna")]),
 "shibou-05": ("漁業の仕事で、一番楽しみなことは何ですか。", "Apa yang paling Anda nantikan dari pekerjaan perikanan?", "大きな魚が取れたときの喜びを味わいたいです。日本の漁の方法も学びたいです。", "Saya ingin merasakan kegembiraan saat mendapat ikan besar. Saya juga ingin belajar cara menangkap ikan di Jepang.", [("楽しみ", "dinantikan"), ("漁", "penangkapan ikan"), ("喜び", "kegembiraan")]),
 "shigoto-01": ("漁業の主な仕事は何だと思いますか。", "Menurut Anda, apa pekerjaan utama perikanan?", "船で魚を取ったり、貝や海藻を育てたりする仕事だと思います。取ったあとの整理も大切だと思います。", "Saya kira pekerjaannya menangkap ikan dengan kapal atau membudidayakan kerang dan rumput laut. Merapikan hasil tangkapan juga penting.", [("漁", "penangkapan ikan"), ("養殖", "budidaya"), ("水揚げ", "pendaratan hasil tangkapan")]),
 "shigoto-02": ("朝早くから働くことはできますか。", "Apakah Anda bisa bekerja dari pagi buta?", "はい、できます。漁は朝がとても早いと聞いています。夜は早く寝て、準備します。", "Ya, bisa. Saya dengar melaut dimulai sangat pagi. Malamnya saya tidur lebih awal untuk bersiap.", [("早朝", "pagi buta"), ("準備", "persiapan"), ("早く寝る", "tidur lebih awal")]),
 "shigoto-03": ("寒い日や暑い日でも、海の上で働けますか。", "Bisakah Anda bekerja di laut walau cuaca dingin atau panas?", "はい、大丈夫です。寒い日は服をたくさん着て、暑い日はこまめに水を飲みます。", "Ya, tidak masalah. Saat dingin saya memakai banyak lapis pakaian, saat panas saya sering minum air.", [("寒い", "dingin"), ("暑い", "panas"), ("こまめに", "sering/rutin")]),
 "shigoto-04": ("波が高い日や天気が悪い日は、どう思いますか。", "Bagaimana pendapat Anda saat ombak tinggi atau cuaca buruk?", "危ないので、無理をしてはいけないと思います。船長の判断を守ります。", "Karena berbahaya, menurut saya tidak boleh memaksakan diri. Saya akan mengikuti keputusan kapten.", [("波", "ombak"), ("危ない", "berbahaya"), ("船長", "kapten kapal"), ("判断", "keputusan")]),
 "shigoto-05": ("体力が必要な仕事ですが、大丈夫ですか。", "Pekerjaan ini butuh stamina, apakah Anda baik-baik saja?", "はい、大丈夫です。毎朝ジョギングをして、体力をつけています。", "Ya, tidak masalah. Setiap pagi saya jogging untuk membangun stamina.", [("体力", "stamina"), ("ジョギング", "jogging"), ("健康", "kesehatan")]),
 "shigoto-06": ("船の上で、何日も帰れないことがあっても大丈夫ですか。", "Apakah Anda baik-baik saja bila beberapa hari tidak bisa pulang dari kapal?", "大丈夫です。家族とはメッセージで連絡します。みんなで協力して、がんばります。", "Tidak masalah. Saya akan menghubungi keluarga lewat pesan. Kami akan bekerja sama dan berusaha.", [("何日も", "berhari-hari"), ("連絡", "menghubungi"), ("協力", "kerja sama")]),
 "shigoto-07": ("船や漁の道具を使うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memakai kapal atau alat tangkap?", "使う前に、道具に問題がないか確認します。ロープや網には、手や足を引っかけないように気をつけます。", "Sebelum dipakai, saya memeriksa apakah alatnya bermasalah. Saya berhati-hati agar tangan dan kaki tidak tersangkut tali atau jaring.", [("道具", "alat"), ("網", "jaring"), ("ロープ", "tali"), ("確認", "memastikan")]),
 "shigoto-08": ("魚のにおいや汚れがある環境でも大丈夫ですか。", "Apakah Anda baik-baik saja dengan lingkungan yang berbau dan kotor oleh ikan?", "はい、大丈夫です。仕事のあとで、きれいに洗います。においにも、すぐ慣れると思います。", "Ya, tidak masalah. Setelah kerja saya mencuci bersih. Saya kira saya akan cepat terbiasa dengan baunya.", [("におい", "bau"), ("汚れ", "kotoran"), ("慣れる", "terbiasa"), ("洗う", "mencuci")]),
 "shigoto-09": ("魚を新鮮に保つために、大切なことは何だと思いますか。", "Menurut Anda, apa yang penting untuk menjaga ikan tetap segar?", "取ったあと、すぐに氷で冷やすことだと思います。魚をていねいに扱うことも大切です。", "Menurut saya, segera mendinginkan ikan dengan es setelah ditangkap. Menangani ikan dengan hati-hati juga penting.", [("新鮮", "segar"), ("氷", "es"), ("冷やす", "mendinginkan"), ("扱う", "menangani")]),
 "shigoto-10": ("船が港を出てから戻るまで、どんな作業がありますか。", "Pekerjaan apa saja sejak kapal meninggalkan pelabuhan sampai kembali?", "出港して、網を入れて、魚を取ります。そのあと、魚を分けて、氷に入れます。港に戻ったら、水揚げをします。", "Berangkat dari pelabuhan, menurunkan jaring, dan menangkap ikan. Lalu memilah ikan dan memasukkannya ke es. Setelah kembali ke pelabuhan, ikan didaratkan.", [("出港", "berangkat dari pelabuhan"), ("水揚げ", "pendaratan ikan"), ("選別", "pemilahan")]),
 "shigoto-11": ("魚の種類を、どうやって分けますか。", "Bagaimana Anda memilah jenis ikan?", "先輩に教えてもらって、大きさや形を見て分けます。分からない魚は、すぐに聞きます。", "Saya diajari senior dan memilah menurut ukuran dan bentuk. Kalau tidak tahu jenis ikan, saya segera bertanya.", [("種類", "jenis"), ("大きさ", "ukuran"), ("形", "bentuk"), ("分ける", "memilah")]),
 "shigoto-12": ("海の上で、天気や波の様子を見ることは、なぜ大切ですか。", "Mengapa penting memperhatikan cuaca dan keadaan ombak di laut?", "天気が急に変わると、とても危ないからです。早めに分かれば、安全に港へ戻れます。", "Karena jika cuaca berubah mendadak sangat berbahaya. Kalau tahu lebih awal, kita bisa kembali ke pelabuhan dengan selamat.", [("天気", "cuaca"), ("急に", "mendadak"), ("安全", "keselamatan"), ("港", "pelabuhan")]),
 "shigoto-13": ("貝や海藻を育てる仕事で、大切なことは何だと思いますか。", "Menurut Anda, apa yang penting dalam budidaya kerang atau rumput laut?", "毎日、様子を見ることだと思います。水の温度やきれいさにも気をつけて、記録します。", "Menurut saya, memeriksa keadaannya setiap hari. Saya juga memperhatikan suhu dan kebersihan air serta mencatatnya.", [("養殖", "budidaya"), ("水温", "suhu air"), ("記録", "pencatatan"), ("様子を見る", "mengamati keadaan")]),
 "taiou-02": ("取った魚を、だめにしてしまったら、どうしますか。", "Apa yang Anda lakukan kalau ikan hasil tangkapan jadi rusak?", "すぐに正直に報告します。どうしてそうなったか考えて、次は氷や温度に気をつけます。", "Saya segera melapor jujur. Saya memikirkan penyebabnya dan lebih memperhatikan es dan suhu berikutnya.", [("だめにする", "merusak"), ("報告", "melapor"), ("原因", "penyebab"), ("温度", "suhu")]),
 "taiou-06": ("天気が急に悪くなって、予定が変わったら、どうしますか。", "Apa yang Anda lakukan kalau cuaca mendadak buruk dan rencana berubah?", "船長の指示をよく聞いて、安全を第一に動きます。わからないときは、すぐに聞きます。", "Saya mendengarkan instruksi kapten dan bergerak dengan mengutamakan keselamatan. Kalau tidak paham, saya langsung bertanya.", [("急に", "mendadak"), ("指示", "instruksi"), ("安全第一", "keselamatan utama"), ("予定", "rencana")]),
 "taiou-08": ("出港の時間が、急に早くなったら、どうしますか。", "Apa yang Anda lakukan kalau jam berangkat mendadak dimajukan?", "連絡をよく聞いて、すぐに準備します。前の日に、道具や服を用意しておきます。", "Saya mendengar pemberitahuan dan segera bersiap. Sehari sebelumnya saya menyiapkan alat dan pakaian.", [("出港", "keberangkatan kapal"), ("準備", "persiapan"), ("連絡", "pemberitahuan")]),
 "taiou-11": ("忙しい漁の時期に、休みが少なくなったとき、どう気持ちを保ちますか。", "Bagaimana Anda menjaga semangat saat musim ikan sibuk dan libur sedikit?", "忙しい時期は短いと理解しています。短い休みでも、しっかり寝て、食事をとって、体調を保ちます。", "Saya paham musim sibuk itu singkat. Walau liburnya singkat, saya tidur cukup, makan baik, dan menjaga kondisi badan.", [("繁忙期", "musim sibuk"), ("休む", "istirahat"), ("体調", "kondisi badan")]),
 "taiou-12": ("港の人に、方言で話されて分からないとき、どうしますか。", "Apa yang Anda lakukan kalau orang di pelabuhan berbicara dialek dan Anda tidak paham?", "「すみません、ゆっくりお願いします」と言います。分からない言葉は、メモして、あとで意味を聞きます。", "Saya bilang \"Maaf, tolong lebih pelan\". Kata yang tidak saya paham saya catat dan tanyakan artinya nanti.", [("方言", "dialek"), ("ゆっくり", "pelan"), ("意味", "arti")]),
 "tim-01": ("漁のとき、チームの人と、どのように作業を分けますか。", "Saat melaut, bagaimana Anda membagi tugas dengan tim?", "船長の指示で、網を引く人、魚を分ける人などに分かれます。終わった人は、他の人を手伝います。", "Sesuai instruksi kapten, ada yang menarik jaring dan ada yang memilah ikan. Yang selesai membantu yang lain.", [("分担", "pembagian tugas"), ("網を引く", "menarik jaring"), ("手伝う", "membantu")]),
 "tim-02": ("船長の指示が分からなかったとき、どうしますか。", "Apa yang Anda lakukan kalau tidak paham instruksi kapten?", "すぐに「もう一度お願いします」と聞きます。海の上では、わからないまま動くと危ないからです。", "Saya segera meminta \"Tolong ulangi\". Di laut, bergerak tanpa paham itu berbahaya.", [("船長", "kapten"), ("指示", "instruksi"), ("確認", "memastikan")]),
 "tim-03": ("船の上で、一緒に働く人と、どのようにコミュニケーションをとりますか。", "Bagaimana Anda berkomunikasi dengan rekan kerja di atas kapal?", "短い言葉と、大きい声で伝えます。分かったときは「はい」とはっきり返事をします。", "Saya menyampaikan dengan kata singkat dan suara keras. Saat paham, saya menjawab \"Ya\" dengan jelas.", [("大きい声", "suara keras"), ("返事", "jawaban"), ("伝える", "menyampaikan")]),
 "tim-04": ("船の上の先輩や仲間と、どのように仲良くなりたいですか。", "Bagaimana Anda ingin akrab dengan senior dan rekan di kapal?", "毎日、元気にあいさつをします。教えてもらったときは、「ありがとうございます」と言います。", "Setiap hari saya menyapa dengan semangat. Saat diajari, saya mengatakan \"Terima kasih\".", [("あいさつ", "salam"), ("仲間", "rekan"), ("仲良くなる", "menjadi akrab")]),
 "anzen-01": ("船の上では、何を必ず身につけますか。", "Apa yang wajib dikenakan di atas kapal?", "ライフジャケットを必ず着ます。すべりにくい長靴と手袋も使います。", "Saya wajib memakai jaket pelampung. Saya juga memakai sepatu bot anti-licin dan sarung tangan.", [("ライフジャケット", "jaket pelampung"), ("長靴", "sepatu bot"), ("すべる", "licin")]),
 "anzen-02": ("船の上で、海に落ちないために、何に気をつけますか。", "Apa yang Anda perhatikan agar tidak jatuh ke laut?", "甲板は、ぬれてすべりやすいので、ゆっくり歩きます。揺れるときは、手すりを持ちます。", "Karena dek basah dan licin, saya berjalan pelan. Saat kapal bergoyang saya berpegangan pada pagar.", [("甲板", "dek"), ("手すり", "pegangan/pagar"), ("すべりやすい", "mudah licin")]),
 "anzen-03": ("機械や網を使うとき、事故を防ぐために何をしますか。", "Apa yang Anda lakukan untuk mencegah kecelakaan saat memakai mesin dan jaring?", "使う前に、機械の状態を確認します。動いているときは、近づきすぎません。ロープに足を入れないようにします。", "Sebelum dipakai, saya memeriksa kondisi mesin. Saat bergerak, saya tidak mendekat terlalu dekat. Saya menghindari memasukkan kaki ke tali.", [("機械", "mesin"), ("ロープ", "tali"), ("近づく", "mendekat")]),
 "anzen-04": ("もし仲間が海に落ちたら、どうしますか。", "Apa yang Anda lakukan kalau rekan jatuh ke laut?", "大きい声で「落ちた」と知らせて、すぐ船長に言います。自分で飛び込まないで、浮き輪を投げます。", "Saya berteriak \"Ada yang jatuh\" dan segera memberi tahu kapten. Saya tidak melompat sendiri, tetapi melempar pelampung.", [("落ちる", "jatuh"), ("浮き輪", "pelampung"), ("知らせる", "memberi tahu")]),
 "seikatsu-07": ("海の近くの町での生活に、不便なことがあっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan ketidaknyamanan hidup di kota pesisir?", "大丈夫です。お店が遠いときは、まとめて買い物をします。バスの時間も調べます。", "Tidak masalah. Kalau toko jauh, saya belanja sekaligus. Saya juga mengecek jadwal bus.", [("不便", "tidak nyaman"), ("まとめて", "sekaligus"), ("調べる", "mengecek")]),
 "seikatsu-08": ("日本の漁業や、海の食べ物について、知っていることはありますか。", "Apa yang Anda ketahui tentang perikanan dan makanan laut Jepang?", "日本では、寿司や刺身など、魚をよく食べると聞きました。季節によって、取れる魚が違うことも知っています。", "Saya dengar orang Jepang sering makan ikan, seperti sushi dan sashimi. Saya juga tahu ikan yang ditangkap berbeda menurut musim.", [("刺身", "sashimi"), ("季節", "musim"), ("魚介類", "hasil laut")]),
 "mokuhyou-05": ("日本で漁業を学んだあと、自分の国でどんなことをしたいですか。", "Setelah belajar perikanan di Jepang, apa yang ingin Anda lakukan di negara sendiri?", "日本で学んだ魚の扱い方や、安全の方法を使って、自分の町の漁業をよくしたいです。", "Saya ingin menggunakan cara menangani ikan dan keselamatan yang saya pelajari di Jepang untuk memperbaiki perikanan di kota saya.", [("扱い方", "cara menangani"), ("安全", "keselamatan"), ("漁業", "perikanan")]),
})
